    public static function svg(string $key): ?string
    {
        $path = self::all()[$key]['path'] ?? null;

        return $path ? '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="'.$path.'"/></svg>' : null;
    }

    /** Icon key guessed from a link, e.g. github.com → github. */
    public static function guess(string $url): string
    {
        $host = strtolower(preg_replace('/^www\./', '', (string) parse_url($url, PHP_URL_HOST)));

        foreach (self::all() as $key => $icon) {
            foreach ($icon['hosts'] as $h) {
                if ($host === $h || str_ends_with($host, '.'.$h)) {
                    return $key;
                }
            }
        }

        return 'website';
    }

    /** @return array<string, string> key => label, for a select field */
    public static function options(): array
    {
        return array_map(fn (array $i): string => $i['label'], self::all());
    }
